/bin/zsh -lc "node - <<'NODE'
const fs=require('fs'), crypto=require('crypto');
const m=JSON.parse(fs.readFileSync('.planning/milestones/M002/design/config-portability/evidence/M002-UI-33-R3-source-manifest.json'));
const h=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
let mismatches=[];
for(const [p,want] of Object.entries(m.files)){let got;try{got=h(p)}catch(e){got='MISSING'} if(got"'!==want)mismatches.push({p,want,got})}
console.log(JSON.stringify({manifest_sha256:h('"'.planning/milestones/M002/design/config-portability/evidence/M002-UI-33-R3-source-manifest.json'),archive_sha256:h(m.archive.path),archive_expected:m.archive.sha256,archive_bytes:fs.statSync(m.archive.path).size,archive_bytes_expected:m.archive.bytes,file_hashes_checked:Object.keys(m.files).length,file_hash_mismatches:mismatches.length,mismatches},null,2));
